import{_ as s,o as a,c as t,ah as i}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"実行の意味論","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/execution-semantics.md","filePath":"ja/guide/execution-semantics.md"}'),d={name:"ja/guide/execution-semantics.md"};function c(n,e,o,l,p,r){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="実行の意味論" tabindex="-1">実行の意味論 <a class="header-anchor" href="#実行の意味論" aria-label="Permalink to &quot;実行の意味論&quot;">​</a></h1><p>Celox のクロックを駆動する操作は IEEE 1800 のスケジューリングで定義されて います。イベントベースの <code>Simulator</code> では、ホストの各呼び出しが 1 つの タイムスロットで、その中で決まった SystemVerilog の文が実行されます。Veryl ネイティブテストベンチのクロック・リセットコンポーネントは、決まった SystemVerilog のコードです。そのコードを IEEE 1800 準拠のシミュレータで 実行すると、Celox と同じ値が観測されます。</p><p>以下のコードで、<code>s</code> はイベント（クロックまたはリセットのポート）の信号、 <code>A</code> はそのアクティブレベル、<code>I</code> は非アクティブレベルです。<code>A</code> は 立ち上がりエッジのクロックと active-high リセットで 1、立ち下がりエッジの クロックと active-low リセットで 0 です。Veryl の抽象 <code>clock</code> 型と <code>reset</code> 型では、ビルドのクロック種別とリセット種別に従います。</p><p>リセットの極性と同期・非同期は設計側の性質で、ここの規則には現れません。 Veryl は <code>always_ff (clk, rst) { if_reset ... }</code> を、非同期 active-low リセットなら <code>always_ff @(posedge clk, negedge rst_n) if (!rst_n) ...</code> に、同期リセットなら <code>always_ff @(posedge clk) if (!rst_n) ...</code> に出力し、 IEEE 1800 のスケジューラが信号の動きだけからそれぞれの振る舞いを作ります。</p><h2 id="simulator-api" tabindex="-1"><code>Simulator</code> API <a class="header-anchor" href="#simulator-api" aria-label="Permalink to &quot;\`Simulator\` API&quot;">​</a></h2><p><code>Simulator</code> にはシミュレーション時刻がありませんが、スケジューリングは IEEE 1800 のシミュレーションと同じです。ホストの各呼び出しは 1 つの タイムスロット（IEEE 1800-2023 4.4）です。呼び出しの文はそのスロットで 実行され、スロットはすべての領域が空になるまで進み、次の呼び出しは後の スロットで始まります。呼び出しと呼び出しの間の読み出し（<code>get</code>、 <code>sim.dut.x</code>）は、完了したスロットの状態を見ます。</p><table tabindex="0"><thead><tr><th>呼び出し</th><th>スロットの文</th></tr></thead><tbody><tr><td><code>set(x, v)</code>、<code>sim.dut.x = v</code></td><td><code>x = v;</code></td></tr><tr><td><code>edge(e, Rising)</code>、<code>posedge(e)</code></td><td><code>s &lt;= 1;</code></td></tr><tr><td><code>edge(e, Falling)</code>、<code>negedge(e)</code></td><td><code>s &lt;= 0;</code></td></tr><tr><td><code>active_edge(e)</code> / <code>inactive_edge(e)</code></td><td><code>s &lt;= A;</code> / <code>s &lt;= I;</code></td></tr><tr><td><code>edges([(e1, l1), …, (ek, lk)])</code></td><td><code>s1 &lt;= l1; … sk &lt;= lk;</code></td></tr><tr><td><code>tick(e)</code></td><td><code>s &lt;= A;</code> そして次のスロットで <code>s &lt;= I;</code></td></tr><tr><td><code>tick(e, n)</code></td><td><code>tick(e)</code> を <code>n</code> 回</td></tr><tr><td><code>tick_events([e1, …, ek])</code></td><td><code>s1 &lt;= A1; … sk &lt;= Ak;</code> そして次のスロットで <code>s1 &lt;= I1; … sk &lt;= Ik;</code></td></tr></tbody></table><p>ホストは設計内のプロセスではないので、上の表に遅延は現れません。スロットは 設計が 1 つの文に応答する単位です。同じ列を SystemVerilog シミュレータで 実行するには、文を 1 つの <code>initial</code> プロセスに並べ、各文の後に時間精度 1 単位の遅延を置きます。<code>Simulator</code> は遅延を含む設計を受け付けないので、 その単位の長さは観測できません。</p><p>ここから次のことが従います。</p><ul><li>tick はクロック 1 周期です。どちらかのエッジに反応するドメインはすべて 実行されます。イベント自身のドメインはアクティブエッジで、逆エッジの ドメイン（<code>@(negedge clk)</code>、<code>~clk</code> をクロックとするレジスタ）や <code>clk &amp; en</code> のように信号から計算されるクロックは、それぞれが見るエッジで 実行されます。信号は非アクティブレベルで終わります。</li><li>すでにアクティブレベルにある信号では、<code>s &lt;= A</code> は何も変えないので アクティブエッジは起きません。2 値で 0 から始まる active-low リセットを tick すると、解除されるだけです。リセットをアサートするには <code>negedge(rst)</code> か <code>active_edge(rst)</code> を使います。</li><li>1 つのスロットで起動されたドメインは、ノンブロッキング代入と同じく、 スロット前の状態をサンプルしてからまとめて更新します。複数クロックの 同時エッジ（<code>edges</code>、<code>tick_events</code>）では、共有スロットの前の値を互いに サンプルします。レジスタによる分周クロックのように、そのスロット自身が 動かすクロックは、コミットの後にスロット内で立ち上がり、そのドメインも 同じスロットで実行されます。</li><li>4 値の設計では、不定レベルはどちらのレベルとしても扱われます。<code>x</code> から 1 は立ち上がりエッジ、<code>x</code> から 0 は立ち下がりエッジです （IEEE 1800-2023 Table 9-2）。</li></ul><p><code>set</code> や <code>sim.dut</code> 経由の書き込みで、イベント信号や、それから計算される クロックを動かしてはいけません。Celox がドメインを実行するのは上の エッジ操作だけです。これらの信号は <code>edge</code> や <code>tick</code> とその派生で駆動して ください。</p><h3 id="ホストからのリセット" tabindex="-1">ホストからのリセット <a class="header-anchor" href="#ホストからのリセット" aria-label="Permalink to &quot;ホストからのリセット&quot;">​</a></h3><p>クロック <code>n</code> 周期のリセットは、リセットのアクティブエッジ、クロックの <code>n</code> 回の tick、リセットの非アクティブエッジです。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">activeEdge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rst);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(clk, n);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inactiveEdge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rst);</span></span></code></pre></div><p>非同期リセットのドメインは最初のスロットで、クロックエッジの前に実行 されます。同期リセットは最初の tick でリセットされます。この列は、後述の テストベンチの <code>rst.assert(n)</code> と同じスロット列です。</p><h3 id="複数のクロック" tabindex="-1">複数のクロック <a class="header-anchor" href="#複数のクロック" aria-label="Permalink to &quot;複数のクロック&quot;">​</a></h3><p>tick はそのイベントの 1 周期なので、2 つのクロック入力の位相関係は表せ ません。<code>clk</code> と、その 2 倍の周期をもつ <code>clk_half</code> のように周波数比のある クロックは、<code>edges</code> で瞬間ごとに駆動します。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([[clk, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;posedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [clkHalf, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;posedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([[clk, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;negedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([[clk, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;posedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [clkHalf, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;negedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([[clk, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;negedge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]);</span></span></code></pre></div><p>または、入力ごとに <code>addClock</code> した timed <a href="./writing-tests.html#タイムベースシミュレーション"><code>Simulation</code></a> を使います。 <code>tick_events([clk, clk_half])</code> と <code>tick(clk)</code> を交互に呼ぶ方法は、 立ち上がりエッジだけを見るドメインに対してのみ同じ結果になります。 <code>clk_half</code> が次の立ち上がりではなく <code>clk</code> の立ち下がりと同時に立ち下がる からです。</p><h2 id="veryl-ネイティブテストベンチ" tabindex="-1">Veryl ネイティブテストベンチ <a class="header-anchor" href="#veryl-ネイティブテストベンチ" aria-label="Permalink to &quot;Veryl ネイティブテストベンチ&quot;">​</a></h2><p>Veryl テストベンチの initial ブロックは SystemVerilog の <code>initial</code> プロセスで、<code>$finish()</code> は <code>$finish</code> です。ホストと違い、これらの プロセスにはシミュレーション時刻があります。以下のコンポーネントは SystemVerilog のコードで、その遅延はテストベンチの時間です。</p><h3 id="tb-clock-gen" tabindex="-1"><code>$tb::clock_gen</code> <a class="header-anchor" href="#tb-clock-gen" aria-label="Permalink to &quot;\`$tb::clock_gen\`&quot;">​</a></h3><p><code>inst clk: $tb::clock_gen #(period: P);</code> は、待つプロセスがあるかどうかに かかわらず時刻 0 から動くクロック生成器です。<code>P</code> の既定値は 2 で、最小値も 2 です。<code>H = ceil(P / 2)</code>、<code>L = floor(P / 2)</code> として:</p><div class="language-systemverilog vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">systemverilog</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bit clk = 1&#39;b0;</span></span>
<span class="line"><span>initial forever begin</span></span>
<span class="line"><span>  clk &lt;= 1&#39;b1; #H;</span></span>
<span class="line"><span>  clk &lt;= 1&#39;b0; #L;</span></span>
<span class="line"><span>end</span></span></code></pre></div><h3 id="clk-next-n" tabindex="-1"><code>clk.next(n)</code> <a class="header-anchor" href="#clk-next-n" aria-label="Permalink to &quot;\`clk.next(n)\`&quot;">​</a></h3><div class="language-systemverilog vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">systemverilog</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task automatic clk_next(int unsigned n);</span></span>
<span class="line"><span>  if (n != 0) begin</span></span>
<span class="line"><span>    repeat (n) @(posedge clk);</span></span>
<span class="line"><span>    #P;</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>endtask</span></span></code></pre></div><p><code>clk.next()</code> は <code>clk.next(1)</code> です。</p><ul><li>プロセスは、待っていた <code>n</code> 回目の立ち上がりエッジから 1 周期後、次の 立ち上がりの直前に再開します。そのため、その周期の両エッジの後の状態を 観測します。クロックは Low で、立ち下がりエッジのドメインは実行済みです。</li><li>クロックはノンブロッキング代入で立ち上がり、同じ時刻に再開した プロセスの実行後に立ち上がります。そのため、2 つの <code>next</code> の間で プロセスが書き込んだ値は、競合なく次の立ち上がりエッジでサンプルされます。</li><li>複数の initial プロセスや周期の異なる複数のクロックに、追加の規則は ありません。これらは並行する SystemVerilog のプロセスです。誰も待って いないクロックも動き続け、そのドメインを駆動します。</li></ul><h3 id="tb-reset-gen" tabindex="-1"><code>$tb::reset_gen</code> <a class="header-anchor" href="#tb-reset-gen" aria-label="Permalink to &quot;\`$tb::reset_gen\`&quot;">​</a></h3><p><code>inst rst: $tb::reset_gen #(cycles: C) (clk);</code> は、テストベンチの <code>reset</code> 型のリセットネットで、時刻 0 から非アサート状態です。</p><div class="language-systemverilog vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">systemverilog</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bit rst = I;</span></span></code></pre></div><h3 id="rst-assert-n" tabindex="-1"><code>rst.assert(n)</code> <a class="header-anchor" href="#rst-assert-n" aria-label="Permalink to &quot;\`rst.assert(n)\`&quot;">​</a></h3><p><code>P</code> を生成器に渡したクロックの周期として:</p><div class="language-systemverilog vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">systemverilog</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task automatic rst_assert(int unsigned n);</span></span>
<span class="line"><span>  if (n == 0) n = 1;</span></span>
<span class="line"><span>  rst = A;</span></span>
<span class="line"><span>  repeat (n) @(posedge clk);</span></span>
<span class="line"><span>  #P;</span></span>
<span class="line"><span>  rst = I;</span></span>
<span class="line"><span>endtask</span></span></code></pre></div><p><code>rst.assert()</code> は <code>rst.assert(C)</code> で、<code>C</code> の既定値は 3 です。</p><ul><li>アサートは、他のテストベンチの書き込みと同じく、プロセスが到達した 時点でのブロッキング書き込みです。非同期リセットのドメインは、クロック エッジなしに、そのクロックが動いているかどうかにかかわらず、その瞬間に 実行されます。同期リセットのドメインは次の立ち上がりエッジでリセット されます。</li><li>レベルは <code>clk</code> の <code>n</code> 周期保持されます。次の立ち上がりエッジ、または 同じ瞬間の立ち上がりエッジ（クロックはプロセスの書き込み後に立ち上がる ため）から始まる <code>n</code> 回の立ち上がりエッジと、その最後のエッジの後の 1 周期です。どちらの種類のリセットも <code>n</code> 回のリセットエッジを見て、 <code>n + 1</code> 回目のエッジの前に解除されます。</li><li>プロセスの再開とリセットの解除は、<code>next</code> が再開するのと同じ位相、つまり 最後に待ったエッジから 1 周期後、次のエッジの直前です。その後の書き込みは 競合なくそのエッジでサンプルされ、<code>rst.assert(n); clk.next(m);</code> は <code>n + m</code> 周期です。</li><li><code>rst.assert(0)</code> は <code>rst.assert(1)</code> です。アサートしたスロットで解除される リセットは SystemVerilog ではグリッチなので、意味を与えません。</li></ul><p>このページが定義するのは <code>$tb::clock_gen</code>、<code>clk.next</code>、<code>$tb::reset_gen</code>、 <code>rst.assert</code> です。他のテストベンチコンポーネント <code>$tb::file</code> と <code>$tb::random</code> はスケジューリングに関与しません。</p>`,37)])])}const g=s(d,[["render",c]]);export{k as __pageData,g as default};
